// Doubles groups every generated spy for one test.
type Doubles struct {
	CandidateGroups       *CandidateGroupsSpy
	ClassificationHistory *ClassificationHistorySpy
	ClassificationQueue   *ClassificationQueueSpy
	Classifier            *ClassifierSpy
	CommentArchive        *CommentArchiveSpy
	GitHub                *GitHubSpy
	PromotionRuleCatalog  *PromotionRuleCatalogSpy
	RepositoryDirectory   *RepositoryDirectorySpy
	RuleFeedback          *RuleFeedbackSpy
	SeedCatalog           *SeedCatalogSpy
}

// NewDoubles composes and registers every generated spy around the supplied implementations.
func NewDoubles(t *testing.T, candidateGroups CandidateGroups, classificationHistory ClassificationHistory, classificationQueue ClassificationQueue, classifier ports.Classifier, commentArchive CommentArchive, gitHub ports.CodeReviewGateway, promotionRuleCatalog PromotionRuleCatalog, repositoryDirectory RepositoryDirectory, ruleFeedback RuleFeedback, seedCatalog SeedCatalog) *Doubles {
	value := &Doubles{
		CandidateGroups:       NewCandidateGroupsSpy(t, candidateGroups),
		ClassificationHistory: NewClassificationHistorySpy(t, classificationHistory),
		ClassificationQueue:   NewClassificationQueueSpy(t, classificationQueue),
		Classifier:            NewClassifierSpy(t, classifier),
		CommentArchive:        NewCommentArchiveSpy(t, commentArchive),
		GitHub:                NewGitHubSpy(t, gitHub),
		PromotionRuleCatalog:  NewPromotionRuleCatalogSpy(t, promotionRuleCatalog),
		RepositoryDirectory:   NewRepositoryDirectorySpy(t, repositoryDirectory),
		RuleFeedback:          NewRuleFeedbackSpy(t, ruleFeedback),
		SeedCatalog:           NewSeedCatalogSpy(t, seedCatalog),
	}
	return value
}
